class AtCoder {

    final int N;
    List<Long> list;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        list = new ArrayList<>(N);
        for (int i = 0; i < N; i++) {
            long a = sc.nextLong();
            list.add(a);
        }
    }

    void solve(PrintWriter out) {
        if (list.contains(0L)) {
            out.println(0L);
            return;
        }
        try {
            long ans = 1;
            for (long a : list) {
                ans = Math.multiplyExact(ans, a);
            }
            out.println(ans > (long) 1e18 ? "-1" : ans);
        } catch (ArithmeticException ae) {
            out.println("-1");
        }
    }

}

