public class Main {
	// AtCoder Beginner Contest 087
	// https://atcoder.jp/contests/abc087/tasks
	public static void main(String[] args) {
		FastReader sc = new FastReader();
		int n = sc.nextInt();
		int[][] map = new int[2][n];

		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < n; j++) {
				map[i][j] = sc.nextInt();
			}
		}

		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < n; j++) {
				if (i == 0 && j == 0) {
					// Do not thing
				} else if (i == 0 && j > 0) {
					map[i][j] += map[i][j-1];
				} else if (i > 0 && j == 0) {
					map[i][j] += map[i-1][j];
				} else {
					map[i][j] += Math.max(map[i-1][j], map[i][j-1]);
				}
			}
		}

		System.out.println(map[1][n-1]);
	}

	static class FastReader { 
        BufferedReader br; 
        StringTokenizer st; 

        public FastReader() { 
            br = new BufferedReader(new InputStreamReader(System.in)); 
        } 

        String next() { 
            while (st == null || !st.hasMoreElements()) { 
                try { 
                    st = new StringTokenizer(br.readLine()); 
                } catch (IOException  e) { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 

        int nextInt() { 
            return Integer.parseInt(next()); 
        } 

        long nextLong() { 
            return Long.parseLong(next()); 
        } 

        double nextDouble() { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() { 
            String str = ""; 
            try{ 
                str = br.readLine(); 
            } catch (IOException e) { 
                e.printStackTrace(); 
            } 
            return str; 
        } 
    } 
}

