		for(int i=0 ; i<suit.length; i++) {
			for (int num=1; num<=13; num++){
				cards[i*13 + num-1] = suit[i] + " " + num;
				flags[i*13 + num-1] = false;
			}
		}

		for(int j = 0; j<N; j++){
			String set = br.readLine();
			for(int k = 0; k<cards.length; k++) {
