    static int path(int arr[],int n){
        if(n<=1){
            return dp[n] = 0  ; 
        }
        if(n==2){
            return dp[n]=Math.abs(arr[n]-arr[n-1]) ;
        }
        if(dp[n]!=-1){
            return dp[n] ; 
        }
        else {
            return dp[n]= Math.min(Math.abs(arr[n]-arr[n-1])+path(arr, n-1),Math.abs(arr[n-2]-arr[n])+path(arr, n-2)) ; 
        }


