import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int m = sc.nextInt();

		List<String[]> arrList = new ArrayList<>(); 
		while(sc.hasNextLine()) {
			String s = sc.nextLine();
          	if("".equals(s)){
              continue;
            }
			arrList.add(s.split(" "));
		}
		sc.close();

		Map<Integer, Integer> ansMap = new HashMap<>();
		for(int j=1; j<=m; j++) {
			ansMap.put(Integer.valueOf(j), Integer.valueOf(0));
		}
		for(String[] strArr : arrList) {
			makeMap(ansMap, strArr);
		}

		int ans = 0;
		for(Map.Entry<Integer, Integer> entry : ansMap.entrySet()) {
			if (entry.getValue() == n) {
				ans++;
			}
		}
		System.out.println(ans);
	}

	private static void makeMap(Map<Integer, Integer> ansMap, String[] arr) {
		int size = Integer.parseInt(arr[0]);
		for(int i=1; i<=size; i++) {
			Integer key = Integer.parseInt(arr[i]);
			int a = ansMap.get(key).intValue();
			ansMap.put(key, Integer.valueOf(a+1));
		}
	}
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        int k=sc.nextInt();
        long ans=0;


        for(int i=1;i<=k;i++){
            for(int j=1;j<=k;j++){
                for(int l=1;l<=k;l++){
                    ans+=helper(i,j,l);
                }
            }
        }
        System.out.println(ans);
    }

    private static long helper(int i, int j, int k) {

        long temp=gcd(i,j);
        long ans=gcd(temp,k);
        return ans;
    }

    private static long gcd(long a, long b) {
        if(b==0) return a;
        else
            return gcd(b,a%b);
    }
}

