public class Main {

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		int K = sc.nextInt();
		int S = sc.nextInt();
		int count = 0;
		for (int x = 0; x <= K; x++) {
			for (int y = x; y <= K; y++) {
				for (int z = y; z <= K; z++) {
					if (x + y + z == S) {
						if (x == y && y == z)
							count++;
						else if ((x != z && x == y) || (x != z && y == z))
