class Point {
  double x;
  double y;

  public Point(double deg, double r) {
    double rad = deg * Math.PI / 180.0;
    x = Math.cos(rad) * r;
    y = Math.sin(rad) * r;
    // System.out.printf("[%f, %f]\n", x, y);
  }

  public double getX() {
    return x;
  }

  public double getY() {
    return y;
  }

  public double distance(Point b) {
    double c = Math.pow(x - b.getX(), 2);
    double d = Math.pow(y - b.getY(), 2);
    return Math.sqrt(c + d);
  }

  public void show() {
    System.out.printf("[%f, %f]\n", x, y);
  }
}

