  }

  private void solve() {
    try(InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out)) {

      final int n = in.nextInt();
      final int l = in.nextInt();

      int total = 0;
      for (int i = 0; i < n; i++) {
        total += l + i;
      }

      int res = 0;
      for (int i = 0; i < n; i++) {
        int t = 0;
        for (int j = 0; j < n; j++) {
          if(j != i) {
            t += l + j;
          }
        }
        if(abs(total - res) > abs(total - t)) res = t;
      }

      final int ans = res;
      out.println(ans);
    }
    catch(IOException e) {
      System.err.println(e);
    }
  }

