public class Main {

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		int A = sc.nextInt();
		int B = sc.nextInt();
		int C = sc.nextInt();
		int X = sc.nextInt();
		int Y = sc.nextInt();
		long cost = 0;
		if (A + B >= 2 * C) {
			if (X >= Y) {
				cost += Y * 2 * C;
				if (A >= 2 * C)
					cost += (X - Y) * 2 * C;
				else
					cost += (X - Y) * A;
			} else {
				cost += X * 2 * C;
				if (B >= 2 * C)
					cost += (Y - X) * 2 * C;
				else
					cost += (Y - X) * B;
			}
		} else {
			if (X >= Y) {
				cost += Y * (A + B);
				if (A >= 2 * C)
					cost += (X - Y) * 2 * C;
				else
					cost += (X - Y) * A;
			} else {
				cost += X * (A + B);
				if (B >= 2 * C)
					cost += (Y - X) * 2 * C;
				else
					cost += (Y - X) * B;
			}
		}
		System.out.println(cost);

	}

	//以下、自作ライブラリ

