		int cnt = 0;
		for (int i = 0; i < n; i++) {
			long tmp = c;
			for (int j = 0; j < m; j++) {
				tmp += a[i][j] * b[j];
			}

			if (tmp > 0) {
				cnt++;
			}
		}

		pr.println(cnt);
	}

