        long res = dfs(h,map);
        System.out.println(res);
    }

    public static long dfs(long h,HashMap<Long,Long> map)
    {
        long ans=1;
        if(h<=1)return ans;
        if(map.get(h)!=null)return map.get(h);
        long cur=dfs(h/2,map);
        ans+=2*cur;
        map.put(h,ans);
        return ans;
    }
