    	public void solve(int testNumber, MyInput in, PrintWriter out) {
			long N = in.nextLong();
			long wk;
			int cnt;
			int ans = 12;
			for(long i=1; i*i <= N; i++) {
				if(N % i == 0) {
					wk = N / i;
					cnt = Math.max(calc(i), calc(wk));
//					out.println("i = " + i + "  wk = " + wk + "  -->  cnt = " + cnt);
					if(ans > cnt)	ans = cnt;
				}
			}
			out.println(ans);
        }
    }
