        int a = sc.nextInt();
        int b = sc.nextInt();
        int h = sc.nextInt();
        int m = sc.nextInt();
        double hour_angle = (0.5 * (h*60 + m));
        int minute_angle = (6*m);
        double angle = Math.abs(hour_angle - minute_angle);
        angle = Math.min(360-angle, angle);
        angle = Math.toRadians(angle);
        double ans = (a *a) + (b*b) - (2 *a * b * (Math.cos(angle)));
        ans = Math.sqrt(ans);
        out.printf("%.10f",ans);
    }
