			    }
			else if(processed[i].equals("*"))
			    {
				stack[j-2] = stack[j-2] * stack[j-1];
				j--;
			    }
			else if(processed[i].equals("/"))
			    {
				stack[j-2] = stack[j-2]/stack[j-1];
				j--;
			    }
