				a[i] = scan.nextInt();
				sum += a[i];
			}

			ave = (double)sum/n;

			for(i=0; i<n; i++)
			{
				var += ( (a[i] - ave)*(a[i] - ave) );
			}

			std = Math.sqrt(var/n);

			System.out.printf("%.5f\n",std);
		}

		scan.close();
	}
}

