         //取り出すカードの枚数: K
         int K = sc.nextInt();
         sc.close();

         //取り出したカードの総和
         int count = 0;
         //カードの数
         int cardNum = 1;

         for (int num : numList) {
             if (num > 0) {
                 if (num > K) {
                     num = K;
                 }
                 count += (cardNum * num);
                 K -= num;
                 if (K == 0) {
                     break;
                 }
             }
             cardNum--;
         }
         System.out.println(count);

    }

}

