    }

    static long gcd(long a, long b) {
        if(b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }

    // cでもdでも割れない個数
    static long num(long n, long c, long d) {
        // 最大公約数
        long G = gcd(c,d);
        // 最小公倍数
        long L = c / G * d;

        return n - (n/c) - (n/d) + (n/L);
    }
}

