public class Main {
  static InputReader in;
  static PrintWriter out;

  static class Solution {
    void solve() throws IOException {
      while (true) {
        int H = in.nextInt();
        int W = in.nextInt();
        if (H == 0 && W == 0) break;

        for (int i = 0; i < H; i++) {
          if (i % 2 == 0) {
            for (int j = 0; j < W; j++) {
              if (j % 2 == 0) {
                out.print("#");
              } else {
                out.print(".");
              }
            }
            out.print("\n");
          } else {
              for (int j = 0; j < W; j++) {
                if (j % 2 == 1) {
                  out.print("#");
                } else {
                  out.print(".");
                }
              } 
            out.print("\n");
          }
        } 
        out.print("\n");
      }
    }
}

