    public boolean isMultipleOfNine(String num) {
        int sum = 0;
        for (int i = 0; i < num.length(); i++) {
            int digit = num.charAt(i) - '0';
            sum += digit;
        }

        if (num.length() < 10) {
            return sum % 9 == 0;
        } else {
            return isMultipleOfNine(String.valueOf(sum));
        }
