            a[j + 1] = v;
            // 表示
            for (int k = 0; k < a.length; k++) {
                if (k < a.length - 1) {
                    System.out.print(a[k] + " ");
                } else {
                    System.out.println(a[k]);
                }
            }
        }

    }

}

