            h[i] = Integer.parseInt(sc.next());
        }
        int cnt = 0;
        for (int i=0;i<n;i++) {
            if(h[i]>=k)cnt++;
        }
        System.out.println(cnt);

    }

    private static void sort(int[] d, int left, int right){
        if(left>=right){return;}
        int p = d[(left+right)/2];
        int l=left, r=right;
        int tmp;
        while(l<=r){
            while(d[l]>p){l++;}
            while(d[r]<p){r--;}
            if(l<=r){
                tmp=d[l];
                d[l] = d[r];
                d[r] = tmp;
                l++; r--;
            }
        }
        sort(d, left, r);
        sort(d, l, right);
    }
}

