        for (int i = 0; i < n-2; i++){
            if (secondIsMedium(list.get(i), list.get(i+1), list.get(i+2))){
                answer++;
            }
        }

        System.out.println(answer);
    }

    private static boolean secondIsMedium(int one, int two, int three){
        return (one < two && two < three) || (one > two && two > three);
    }
}

