			int t = a[0];
			char cs[] = new char[3];
			Arrays.fill(cs,'-');
			for(int j=0;j<3;j++) {
				if((i>>j&1)==1) {
					cs[j] = '+';
					t += a[j+1];
				}				
				else {
					t -= a[j+1];
				}
			}
			if(t==7) {
