	static int function(long a, long b) {
	    return Math.max(getCount(a), getCount(b));
	}

	static int getCount(long x) {
	    int ans = 0;
	    while (x > 0) {
	        ans++;
	        x /= 10;
	    }
	    return ans;
	}
