	public static long gcd(long a, long b){
		if(a == 0)
			return b;

		return gcd(b%a,a);
	}

	public static long lcm(long[] a, long n){
		long lc = 1;
		for(int i = 0; i < n; i++){
			lc =  (lc * a[i])/gcd(lc,a[i]);
		}
		return lc;
	}

	public static long sum(long[] a,int n,long num){
		long count = 0;
		for(int i = 0; i < n; i++){
			count += (num/a[i]);
		}
		return count;
	}



	}

