		public void solve(int testNumber, InputReader in, PrintWriter out) {
			int a = in.nextInt();
			int b = in.nextInt();
			int c = in.nextInt();
			int d = in.nextInt();

			if (a > c) {
				int temp = a;
				a = c;
				c = temp;
				temp = b;
				b = d;
				d = temp;
			}
