        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            List<String> h = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                String s = in.readString();
                if (!h.contains(s)) {
                    h.add(s);
                }
            }
            if (h.size() < n) {
                out.printLine("No");
            } else {
                int k = h.get(0).length();
                char c = h.get(0).charAt(k - 1);
                int f = 0;
                for (int i = 1; i < n; i++) {
                    if (h.get(i).charAt(0) != c) {
                        f = 1;
                        break;
                    } else {
                        k = h.get(i).length();
                        c = h.get(i).charAt(k - 1);
                    }
                }
                if (f == 0) {
                    out.printLine("Yes");
                } else {
                    out.printLine("No");
                }
            }
        }

