	public static long mincost(long arr[],int n,int i,int k,long memo[])
	{	if(i==n-1)
		return 0;
		if(i>=n)
			return Integer.MAX_VALUE;
		if(memo[i]!=-1)
			return memo[i];
		long a=Integer.MAX_VALUE,b=Integer.MAX_VALUE;
		for(int j=1;j<=k;j++)
		{
			b=mincost(arr, n, i+j, k,memo)+Math.abs(arr[i]-arr[Math.min(n-1, i+j)]);	
			a=Math.min(a, b);
			memo[i]=a;
		}
		return a;
	}

