class AtCoder {

    /* 変数宣言 */
    final int N;
    final int[] P;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        P = new int[N];
        for (int i = 0; i < N; i++) {
            P[i] = sc.nextInt();
        }
    }

    void solve(PrintWriter out) {
        int count = 1;
        int min_index=0;
        for (int i = 1; i < N; i++) {
            boolean flag=true;
            //out.println("--------------------");
            //out.println(i);
            for (int j = min_index; j < i; j++) {
                //out.println(j+", "+P[j]);
                if (P[i]>P[j]) {
                    min_index=j;
                    flag=false;
                    break;
                }
            }
            if (flag) {
                count++;
                min_index=i;
            }
        }
        out.println(count);
    }
}

