import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		String w = scan.nextLine();
		String[] wArray = new String[w.length()];

		for(int i = 0; i < w.length(); i++) {
			wArray[i] = w.substring(i, i + 1);
		}

		List<String> wList = new ArrayList<String>(Arrays.asList(wArray));
		List<String> wHashList = new ArrayList<String>(new HashSet<>(wList));
		int sum = 0;

		for(int i = 0; i < wHashList.size(); i++) {
			for(int j = 0; j < w.length(); j++) {
				if(wHashList.get(i).equals(w.substring(j, j + 1))) {
					sum++;
				}
			}
			if(sum % 2 == 1) {
				break;
			} else {
				sum = 0;
			}
		}

		if(sum % 2 == 1) {
			System.out.println("No");
		} else {
			System.out.println("Yes");
		}

		scan.close();
	}

}

import java.io.BufferedReader;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main implements Closeable {

  private InputReader in = new InputReader(System.in);
  private PrintWriter out = new PrintWriter(System.out);

  public void solve() {
    out.println(2 * Math.PI * in.ni());
  }

  @Override
  public void close() throws IOException {
    in.close();
    out.close();
  }

  static class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
      reader = new BufferedReader(new InputStreamReader(stream), 32768);
      tokenizer = null;
    }

    public String next() {
      while (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public int ni() {
      return Integer.parseInt(next());
    }

    public long nl() {
      return Long.parseLong(next());
    }

    public void close() throws IOException {
      reader.close();
    }
  }

  public static void main(String[] args) throws IOException {
    try (Main instance = new Main()) {
      instance.solve();
    }
  }
}

import java.util.Scanner;
import java.util.ArrayList;
public class Main {
    public static void main (String[] args) {
	Scanner scan = new Scanner(System.in);
	String[] initial = scan.nextLine().split(" ");
	int n = Integer.parseInt(initial[0]);
	int q = Integer.parseInt(initial[1]);
	ArrayList<Process> processes = new ArrayList<Process>();
	for (int i = 0; i < n; i++) {
	    String[] input = scan.nextLine().split(" ");
	    String name = input[0];
	    int time = Integer.parseInt(input[1]);
	    Process p = new Process(name, time);
	    processes.add(p);
	}

	int processTime = 0;
	while (!processes.isEmpty()) {
	    Process p = processes.remove(0);
	    if (p.time > q) {
		processTime += q;
	    } else {
		processTime += p.time;
	    }
	    p.time = p.time - q;
	    if (p.time > 0) {
		processes.add(p);
	    } else {
		System.out.println(p.name + " " + processTime);
	    }
	}
    }

}
class Process {
    String name;
    int time;
    Process (String name, int time) {
	this.name = name;
	this.time = time;
    }
}

