        Scanner sc = new Scanner(System.in);
        x = sc.nextInt();
        int n = sc.nextInt();

        for (int i = 0; i < n; i++) {
            list.add(sc.nextInt());
        }

        System.out.println(dfs(0));
    }

    private static int dfs(int n) {
        if (!(list.contains(x - n))) {
            return x - n;
        } else if (!(list.contains(x + n))) {
            return x + n;
        }
        return dfs(++n);
    }
}

