	private int chkC(int[] args, int total, int[] wk, int currentI, int operand) {

		if (currentI >= 4) {
			return total;
		}
		if (currentI == 0) {
			total += args[0];
		} else {
			switch (operand) {
			case 1:
				total += args[currentI];
				wk[currentI] = operand;
				break;
			case 2:
				total -= args[currentI];
				wk[currentI] = operand;
				break;
			}
		}

		int val1 = chkC(args, total, wk, currentI + 1, 1);
		if (val1 == 7) {
			return 7;
		}
		int val2 = chkC(args, total, wk, currentI + 1, 2);
		if (val2 == 7) {
			return 7;
		}

