			if(a%i==0 && b%i==0){
				n--;
				if(n==0)return i;
			}
		}
		return 0;
	}
	private static int chmax(int a,int b){
		if(a>b) return a;
		else return b;
	}
	private static int chmin(int a,int b){
		if(a<b) return a;
		else return b;
	}
}

