		Max = Math.max(Max, C);
		double pow = Math.pow(2, K);
		if (Max == A) {
			Ans = (A * (int)pow) + B + C;
		} else if (Max == B) {
			Ans = (B * ((int)pow)) + A + C;
		} else {
			Ans = (C * ((int)pow)) + A + B;
		}
		System.out.println(Ans);
	}
}

