	public static void binarySearch(int value) {
		int left = 0, right = s.size();
		while (left < right) {
			int mid = (left + right) / 2;
			if (s.get(mid).intValue() == value) {
				count++;
				break;
			} else if(value < s.get(mid)){
				right = mid;
			} else {
				left = mid + 1;
			}
			mid = (left + right) / 2;
		}
	}

