public class Main{

	public static void main(String args[]){
		FastReader sc = new FastReader();
		StringBuilder sb=new StringBuilder();
		int t,i,n,x;
		t=1;
		while(t-->0){
            x=sc.nextInt();
            n=sc.nextInt();
            int a[]=new int[n];
            HashSet<Integer> set=new HashSet<>();
            for(i=0;i<n;i++){
                a[i]=sc.nextInt();
                set.add(a[i]);
            }
            int temp=x;
            int min=Integer.MAX_VALUE;
            int num=x;
            while(true){
                int val=x-temp;
                if(!set.contains(temp)&&val<min){
                    min=val;
                    num=temp;
                }
                if(val>min)
                    break;
                temp--;
            }
            temp=x;
            while(true){
                int val=temp-x;
                if(!set.contains(temp)&&val<min){
                    min=val;
                    num=temp;
                }
                if(val>min)
                    break;
                temp++;
            }
            sb.append(num).append('\n');
		}
