		} else {
			y = B/D - A/D;
		}

		if (A%E == 0){
			z = B/E - A/E + 1;
		} else {
			z = B/E - A/E;
		}

		System.out.println(B - A + 1 - (x + y - z));
	}

	public static long gcd(long a , long b) {
		if (b==0) {
			return a;
		}
		return gcd(b,a%b);
	}

	private static long lcm(long m, long n) {
        return m * n / gcd(m, n);
    }
}

