         for(int i = 0; i < n; i ++){
            stdDeviation += Math.pow((double)score[i] - avg,2);
         }
         stdDeviation /= (double)n;
         stdDeviation = Math.sqrt(stdDeviation);

         System.out.println(String.format("%.6f",stdDeviation));
      }
