        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            double result = 0;
            for (int i = 1; i <= n; i++) {
                int t = i;
                double tmp = 1;
                while (t < k) {
                    tmp /= 2;
                    t *= 2;
                }
                result += tmp;
            }
            out.println(result / n);

