        if(a <= b) return a;
        else return b;
    }
    public static int max(int a, int b) {
        if(a <= b) return b;
        else return a;
    }
    public static int saiyaku(int a, int b) {
        if(a < b) return saiyaku(b, a);
        if(b == 0) return a;
        int w = b;
        a = a % b;
        b = w;
        return saiyaku(a, b);
    }
}

