        List<Integer> C = new ArrayList<>(N);

        for (int i = 0; i < N; i++) {
            V.add(scan.nextInt());
        }
        for (int i = 0; i < N; i++) {
            C.add(scan.nextInt());
            if (V.get(i) > C.get(i)) {
                result += V.get(i) - C.get(i);
            }
        }
        System.out.println(result);

    }
}

