	private static void gcd(int a, int b)
	{
	    int c;
	    if(a < b)
		swap(a,b);

	    while(b > 0)
		{
		    c = a % b;
		    a = b;
		    b = c;
		}
	System.out.println(a);
	}

    private static void swap(int a, int b)
    {
	int d;
	d = a;
	a = b;
	b = d;
    }
}

