			x=sc.next();
			if(x.charAt(0)=='+'){
				int a=(int) S.pop();
				int b=(int) S.pop();
				S.push(a+b);
			}
			if(x.charAt(0)=='-'){
				int a=(int) S.pop();
				int b=(int) S.pop();
				S.push(b-a);
			}
			if(x.charAt(0)=='*'){
				int a=(int) S.pop();
				int b=(int) S.pop();
				S.push(a*b);
			}else if('0'<=x.charAt(0) && x.charAt(0)<='9'){
				S.push(Integer.parseInt(x));
			}
		}
