        String s = sc.next();
        // 文字列反転処理
        StringBuffer sb = new StringBuffer(s);
        String reversedStr = sb.reverse().toString();

        // 文字列反転リスト
        List<String> list = Arrays.asList("dream", "dreamer", "erase", "eraser");
