            sb.setLength(0);
            sb.append(str);
            reversedList.add(sb.reverse().toString());
        }

        // 正規表現
        String ptnStr = "^(" + String.join("|", reversedList) + ")+$";
        Pattern pattern = Pattern.compile(ptnStr);
        Matcher matcher = pattern.matcher(reversedStr);

        if (matcher.matches()) {
            // 出力
            System.out.println("YES");
        } else {
            // 出力
            System.out.println("NO");
        }
    }
