        System.out.printf("%.10f", 1.0 / RegistersInParallel(N, 0, A));
    }
    public static double RegistersInParallel(int N, int index, int[] A) {
        if (N <= index) {
            return 0.0;
        }
        return (1.0 / A[index]) + RegistersInParallel(N, index + 1, A);
    }
}

