import java.io.DataInputStream;
import java.io.FileInputStream;
import java.io.IOException;

public class Main {
    static class Reader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public Reader(String file_name) throws IOException {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException {
            byte[] buf = new byte[64]; // line length
            int cnt = 0, c;
            while ((c = read()) != -1) {
                if (c == '\n')
                    break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (neg)
                return -ret;
            return ret;
        }

        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public double nextDouble() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();

            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');

            if (c == '.') {
                while ((c = read()) >= '0' && c <= '9') {
                    ret += (c - '0') / (div *= 10);
                }
            }

            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            if (din == null)
                return;
            din.close();
        }
    }
    public static void main(String args[]) throws IOException{
        Reader in = new Reader();
        int n = in.nextInt();

        int[] maxVal = new int[n];
        int[] val = new int[n];
        int[] cost = new int[n];
        for (int i = 0; i < n; i++){
            val[i] = in.nextInt();
            maxVal[i] = val[i];
        }
        for (int i = 0; i < n; i++){
            cost[i] = in.nextInt();
            maxVal[i] -= cost[i];
        }
        maxVal[0] = Math.max(0, maxVal[0]);
        for (int i = 1; i < n; i++){
            maxVal[i] = maxVal[i - 1] + Math.max(0, maxVal[i]);
        }
        System.out.println(maxVal[n - 1]);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

    int count = 0;
    void solve() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        List<Integer> heights = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            heights.add(sc.nextInt());
        }
        calcCount(heights);
        System.out.print(count);
    }

    void calcCount(List<Integer> heights) {
        // 脱出条件
        if (heights.size() == 0) {
            return;
        }
        if (heights.size() == 1) {
            count += heights.get(0);
            return;
        }

        int minHeight = Collections.min(heights);
        if (minHeight > 0) {
            // Integer 型のまま扱えば、もっと簡単にできるかも。
            for (int i = 0; i < heights.size(); i++) {
                int height = heights.get(i);
                heights.set(i, height - minHeight);
            }
            count += minHeight;
        }

        List<Integer> subHeights = new ArrayList<>();
        for (int i = 0; i < heights.size(); i++) {
            int height = heights.get(i);
            // 0 が来て一区切りなので、ここまでをcalcCount()にかける。
            if (height == 0) {
                if (subHeights.size() != 0) {
                    calcCount(subHeights);
                    subHeights.clear();
                }
            }
            // 部分集合の最後まで来たので、ここまでをcalcCount()にかける。
            else if (i == (heights.size() - 1)) {
                subHeights.add(height);
                calcCount(subHeights);
                subHeights.clear();
            }
            else {
                subHeights.add(height);
            }
        }
    }

    // Main
    public static void main(String[] args) {
        new Main().solve();
    }
}

