           if(max < number) max = number;
        }else{
           tm.put(s, 1);
           keyList.add(s);
        }
    }

    Collections.sort(keyList);

    for(int i=0; i<keyList.size(); i++){
      String s = keyList.get(i);
      int number = tm.get(s);
      if(number == max)
        System.out.println(s);
    }

  }
}

