        for(int i = 0; i < N;i++){
            targetMap[2][i+1] = Integer.parseInt(line[i]);
        }

        int indexX = 1;
        while(indexX <= N){

            for(int x = 1;x <= indexX;x++){
                ans += targetMap[1][x];
            }

            for(int nextX = indexX;nextX <= N;nextX++){
                ans += targetMap[2][nextX];
            }

