        if (s.charAt(0) != 'A') return false;
        int cnt = 0;
        for (int i = 1; i < s.length(); i++)
            if (i >= 2 && i <= s.length() - 2) {
                if (s.charAt(i) == 'C') {
                    if (++cnt > 1) return false;
                }else if (!Character.isLowerCase(s.charAt(i)))
                    return false;
            } else if (!Character.isLowerCase(s.charAt(i)))
                return false;
        return cnt == 1;
    }
}

