import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		ShiftOnly solver = new ShiftOnly();
		solver.readInput();
		solver.solve();
		solver.writeOutput();
	}

	static class ShiftOnly {

		private int n;
		private ArrayList<Integer> aInput;

		private Scanner scanner;

		private String answer;

		public ShiftOnly() {
			this.scanner = new Scanner(System.in);
		}

		public void readInput() {
			aInput = new ArrayList<Integer>();
			n = scanner.nextInt();
			for(int i=0; i<n; i++) {
				Integer b =scanner.nextInt();
				aInput.add(b);
			}
		}

		public void solve() {
			int o = 0;
			while(true) {
				for(Integer a :aInput) {
					aInput.set(aInput.indexOf(a), a>>1);
					if(Integer.lowestOneBit(a) == 1) {
						answer = String.valueOf(o);
						return;
					}
				}
				o++;
			}
		}

		public void writeOutput() {
			System.out.println(answer);
		}

	}


}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();

		//A_i:出席番号iの生徒がきたときの教室の生徒の人数＝到着番号
		int[] A = new int[N];
		for(int i=0;i<N;i++) {
			A[i]=sc.nextInt();
		}
		sc.close();

		//B[]:到着した順番に出席番号が並んでる配列
		int[] B = new int[N];

		//出席番号順にfor文を回す。
		//つまり、Aを先頭から見る。
		for(int i=0;i<N;i++) {
			B[A[i]-1]=i+1;//到着番号、出席番号は1からなので配列の要素番号と１ずれてくる。
		}
		//B[]を先頭から出力すれば良い。
		StringBuilder sb = new StringBuilder();
		for(int i=0;i<N;i++) {
			sb.append(B[i]);
			sb.append(" ");
		}
		String ans = sb.toString();

		System.out.println(ans);

	}
}

