class Lcm {
    //gcd 最大公約数
    public static long gcd(long m, long n) {
        if(m < n) return gcd(n,m);
        if(n == 0) return m;
        return gcd(n,m%n);
    }

    public static long lcm(long m, long n) {
        return m * n / gcd(m,n);
    }
}

