			String name = sc.next();
			int second = Integer.parseInt(sc.next());
			tasks[i] = new Task2(name, second);
		}
		int time = 0;
		int head = 0;
		int tail = n;
		while (head != tail) {
			Task2 task = tasks[head];
			head++;
			if (head == 100000) {
				head = 0;
			}
			if (task.getSecond() <= q) {
				time += task.getSecond();
				System.out.print(task.getName() + " ");
				System.out.println(time);

			} else {
				time += q;
				task.setSecond(task.getSecond() - q);
				tasks[tail] = task;
				tail++;
				if (tail == 100000) {
					tail = 0;

				}
			}

		}

	}

}

