	static class TaskX {
		static int overRedCount = 0;

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			int[] a = in.nextIntArray(n);
			int[] color = new int[n];
			for (int i = 0; i < n; i++) {
				color[i] = getColor(a[i]);
			}

			Set<Integer> set = new HashSet<>();
			for (int i : color) {
				if (i == 0) continue;
				set.add(i);
			}

			int min = -1, max = -1;
			if (set.size() == 0) {
				min = 1;
				max = overRedCount;
			} else {
				min = set.size();
				max = set.size()+overRedCount;
			}

			out.println(min+" "+max);

		}

		static int getColor(int a) {
			int ret = 0;
			if (1 <= a && a <= 399) {
				ret = 1;
			} else if (400 <= a && a <= 799) {
				ret = 2;
			} else if (800 <= a && a <= 1199) {
				ret = 3;
			} else if (1200 <= a && a <= 1599) {
				ret = 4;
			} else if (1600 <= a && a <= 1999) {
				ret = 5;
			} else if (2000 <= a && a <= 2399) {
				ret = 6;
			} else if (2400 <= a && a <= 2799) {
				ret = 7;
			} else if (2800 <= a && a <= 3199) {
				ret = 8;
			} else if (3200 <= a) {
				overRedCount++;
			}
			return ret;
		}
	}

