			for (int i = 0; i < intH; i++) {
				// 受けとった横の数字の個数分 処理を繰り返す
				for (int j = 0; j < intW; j++) {
					//縦奇数の場合横の奇数列に＃を表示
					//横偶数の場合横の偶数列に＃を表示する
					if ((i+j)%2 == 0) {
						System.out.print("#");
					//上の条件に当てはまらない場合.を表示する
					} else {
						System.out.print(".");
					}
				}
				// 表示完了後改行する。
				System.out.println();
			}
			//改行する。
			System.out.println();
		}
	}
}

