class point{
	static int d;
	static{
		d = Main.d;
	}
	int[] x;
	point(int... x){
		this.x = x;
	}
	boolean checkGD(point p){
		double dist = 0;
		for(int i = 0; i < d; i++){
			dist += (int)Math.pow(this.x[i] - p.x[i], 2);
		}
		dist = Math.sqrt(dist);
		int idist = (int)dist;
		return (int)(dist * dist * dist * dist) == idist * idist * idist * idist;
//		return dist == dist % 1;
	}
}

