	public static void bubbleSort(int[] a, int x) {
		boolean flag = true;
		count = 0;
		while(flag) {
			flag = false;
			for(int i=x-1;i>0;i--) {
				if(a[i]<a[i-1]) {
					int tmp = a[i];
					a[i] = a[i-1];
					a[i-1] = tmp;
					flag = true;
					count++;
				}
			}
		}
	}

