		public void solve(int numTest, InputReader in, PrintWriter out) {
			int n = in.nextInt();
			String[] inputString = new String[n];
			for(int testcase = -1; ++ testcase < n;) {
				inputString[testcase] = sortString(in.next().toCharArray());
			}
			Arrays.sort(inputString);

			long res = 0, count = 1;
			for(int i = 0; ++i < n;) {
