					res+=count*(count-1)/2;
					count = 0;

				}
				++count;

			}

			out.print(res+count*(count-1)/2);
		}

		private String sortString(char[] charArray) {
			Arrays.sort(charArray);
			return String.copyValueOf(charArray);
		}
	}


