        int n = sc.nextInt();
        List<BigDecimal> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(new BigDecimal(sc.next()));
        }
        Collections.sort(list);
        Deque<BigDecimal> d = new ArrayDeque();
        for (BigDecimal b : list) {
            d.add(b);
        }
        while (d.size() > 1) {
            BigDecimal x = d.poll();
