    public static boolean isPalindrome(String s) {

    	boolean result = true;

    	if(s.length()%2==0) {
    		char[] arr = s.toCharArray();
    		for(int i=0;i<s.length()/2;i++) {
    			if(arr[i]!=arr[s.length()-1-i]) {
    				result = false;
    			}
    		}
    	} else {
    		char[] arr = s.toCharArray();
    		for(int i=0;i<(s.length()-1)/2;i++) {
    			if(arr[i]!=arr[s.length()-1-i]) {
    				result = false;
    			}
    		}
    	}

    	return result;
    }

}

