import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int a[] = new int[n];

        for(int i = 0; i < n; i++){
            a[i] = sc.nextInt();
        }

        Arrays.sort(a);

        int ans = 0;

        for(int i = n-1; i > -1; i--){
            if(i%2==0) ans += a[i];
            else ans -= a[i];
        }

        if(n%2==0) ans *= -1;

        System.out.println(ans);
    }
}

import java.util.*;
public class Main
{
	public static class process
	{
		String name;
		int time;
		public process(String n, int t)
		{
			name=n;
			time=t;
		}
		public String getName()
		{
			return this.name;
		}

		public int getTime()
		{
			return this.time;
		}

		public void run(int t)
		{
			if(this.time-t<0)
			{
				this.time=0;
			}
			else
			{
				this.time = this.time - t;
			}
		}
	}

	public static void main(String[] args)
	{
		Queue<process> q = new LinkedList<process>();
		Scanner in = new Scanner(System.in);
		int procs = in.nextInt();
		int lot = in.nextInt();
		for(int c = 0; c < procs ; c++)
		{
			q.add(new process(in.next(),in.nextInt()));
		}
		in.close();

		//start of algorithm
		int runTime = 0;
		while(!q.isEmpty())
		{
			process p = q.poll();
			int remainingPTime = p.getTime();
			p.run(lot);
			if(p.time == 0)
			{
				runTime+= remainingPTime;
				System.out.println(p.getName()+" "+runTime);
			}
			else 
			{
				runTime+=lot;
				q.add(p);
			}
		}
	}
}

