public class Main {

	public static void InsertionSort(final int N, int[] A){
		for(int i = 0; i < N; i++){
			final int v = A[i];

			int j = i - 1;
			while(j >= 0 && A[j] > v){
				A[j+1] = A[j];
				j--;
			}

			A[j+1] = v;


			for(int k = 0; k < N; k++){
				if(k != 0){ System.out.print(" "); }
				System.out.print(A[k]);
			}
			System.out.println();
		}
	}

	public static void main(String args[]) {
