class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        double N = Integer.parseInt(sc.next());
        double K = Double.parseDouble(sc.next());
        double sum = 0;
        if(N < K) {
            for(int i = 1; i <= N; i++) {
                int kijun = 0;
                if(Math.log(K / i) / Math.log(2) == (int)(Math.log(K / i) / Math.log(2))) {
                    kijun = (int)(Math.log(K / i) / Math.log(2));
                }else {
                    kijun = (int)(Math.log(K / i) / Math.log(2)) + 1;
                }
                sum += 1 / (double)N * Math.pow(0.5, kijun);
            }
            System.out.println(sum);
        }else {

            for(double i = 1; i < K; i++) {
                int kijun = 0;
                if(Math.log(K / i) / Math.log(2) == (int)(Math.log(K / i) / Math.log(2))) {
                    kijun = (int)(Math.log(K / i) / Math.log(2));
                }else {
                    kijun = (int)(Math.log(K / i) / Math.log(2)) + 1;
                }
                sum += (1 / N) * Math.pow(0.5, kijun);
            }

            sum += (1 / N) * (N - K + 1);
            System.out.println(sum);
        }

    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  static class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
      int[] a = new int[n];
      for (int i = 0; i < n; i++)
        a[i] = nextInt();
      return a;
    }

    public long[] nextLongArray(int n) {
      long[] a = new long[n];
      for (int i = 0; i < n; i++)
        a[i] = nextLong();
      return a;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int n = sc.nextInt();
    int[] h = sc.nextIntArray(n);
    int count = 1;
    int max = h[0];
    for (int i = 1; i < n; i++) {
      if (h[i] >= max) {
        count++;
        max = h[i];
      }
    }
    System.out.println(count);
  }
}

