class BubbleSort {
    // -- field
    private int[] sort_array;
    protected int Count;


    // -- Constructor
    private BubbleSort() {}
    public BubbleSort(int[] sort_array) {
	this.sort_array = sort_array;
    }

    // -- Method
    public void display() {
	for (int i = 0; i < this.sort_array.length; i++) {
	    System.out.print(this.sort_array[i]);
	    if(i == this.sort_array.length-1) {
		break;
	    }
	    System.out.print(" ");
	}
	System.out.println();
    }

    public void swap(int x, int y) {
	int temp = this.sort_array[x];
	this.sort_array[x] = this.sort_array[y];
	this.sort_array[y] = temp;
    }

    public void bubbleSort() {
	for (int i = this.sort_array.length - 1; i > 0; i--) {
	    for (int j = 0; j < i; j++) {
		if (this.sort_array[j] > this.sort_array[j + 1]) {
		    swap(j, j + 1);
		    this.Count++;
		}
	    }
	}
    }

    public int getCount() {
    return this.Count;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader r = new BufferedReader(new InputStreamReader(System.in));
        int n = readInt(r);

        if (n <= 1) {
            output(-1);
            return;
        } else {
            int r_i = readInt(r);
            int r_j = readInt(r);
            int delta = r_j - r_i;
            int maxDelta = delta;

            if (r_i > r_j) {
                r_i = r_j;
            }

            for (int i = 0;i < (n -2);i++) {
                r_j = readInt(r);
                delta = r_j - r_i;
                if (delta > maxDelta) {
                    maxDelta = delta;
                }

                if (r_i > r_j) {
                    r_i = r_j;
                }
            }

            output(maxDelta);
        }
    }

    public static void output(int x) {
        System.out.println(x);
    }

    public static int readInt(BufferedReader r) throws Exception {
        return Integer.parseInt(r.readLine());
    }
}

