				count.replace(S, now + 1);
			}
			else {
				count.put(S, 1); //まだMapにキーが登録されていないなら、登録する
			}
		}

		int Max = 0;
		for (int val: count.values()) { 
			if (Max <= val) {
				Max = val;
			}
		}

		StringWriter s = new StringWriter();
	    for (Map.Entry<String, Integer> e :count.entrySet()){
	    	if (e.getValue() == Max) {
	    		s.append(e.getKey() + '\n');
	    	}
	    }
	    System.out.println(s.toString());
	}

}

