public class Main {

	public static boolean palindromic(int t) {
		String ans = String.valueOf(t);
		int n = ans.length();
		for(int i = 0; i < n / 2; ++i) {
			if(ans.charAt(i) != ans.charAt(n - i - 1))return false;
		}
		return true;
	}

