class CommonMultipleNum{
	static long cmn(long num1,long num2){
		//総当たり戦。頑張る。
		long tmp;
		long num3 = num1;
		num3 *= num2;//3点交換
		while((tmp= num1%num2)!=0){
			num1 = num2;
			num2 = tmp;
		}
		return (long)(num3/num2);//キャスト(voidとは)
	}
}

