        dp[0] = 0;
        dp[1] = 0;
        dp[2] = Math.abs(a[1]-a[2]);
        for(int i=3;i<=n;i++){
            int j= i-k;
            int val = Integer.MAX_VALUE;
            if(j<=0) {
                j = 1;
            }
