			String str = br.readLine();
			//キーボード入力した文字列を変数ｓｔｒへ代入
			String[] strAry = str.split(" ");
			//文字列をsplitメソッドを使い、空白で分割する
			//配列を生成する

			W = Integer.parseInt(strAry[0]);
			//Wにキーボード入力の要素[0]を代入する
			H = Integer.parseInt(strAry[1]);
			//Wにキーボード入力の要素[1]を代入する
			x = Integer.parseInt(strAry[2]);
			//Wにキーボード入力の要素[2]を代入する
			y = Integer.parseInt(strAry[3]);
			//Wにキーボード入力の要素[3]を代入する
			r = Integer.parseInt(strAry[4]);
			//Wにキーボード入力の要素[4]を代入する

			//長方形の中に円が含まれるかをif文で判定する
			if(x-r>=0 && x+r<=W &&
					y-r>=0 && y+r<=H){
			//xに関してはx-rをした際に-になると左枠を超える
			//wより横軸x＋rが大きくなると上枠を超える
			//y-rをした際に-になると右枠を超える
			//hより横軸y＋rが大きくなると下枠を超える

				System.out.println("Yes");
				//条件と一致した場合Yesを出力
			}else{
				System.out.println("No");
				//条件と異なる場合はNoを出力
			}
		} catch (IOException e) {
			e.printStackTrace();
		}
	}
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {

	static int n = 0;

	public static void main(String[] args) {


		int anser = 100000000;

		Scanner scan = new Scanner(System.in);

		n = scan.nextInt();

		ArrayList<Integer> address = new ArrayList<>();

		for (int i = 0; i < n; i++) {
			address.add(scan.nextInt());
		}

		Collections.sort(address);

		for (int i = address.get(0); i <= address.get(n-1); i++) {

			int sum = sumList(address,i);

			if(anser > sum) {
				anser = sum;
			}

		}

		System.out.println(anser);
	}

	private static int sumList(ArrayList<Integer> array,int j) {

		int sum =0;

		for (int i = 0; i < n; i++) {
			sum = sum + (j-array.get(i))*(j-array.get(i));
		}

		return sum;

	}

}

import java.util.ArrayDeque;
import java.util.List;
import java.util.Scanner;

class Submission {
  int id;
  boolean ac;
}

public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();

    Submission[] subs = new Submission[M];
    for (int i=0; i<M; i++) {
      int id = sc.nextInt();
      String ac = sc.next();
      subs[i] =  new Submission();
      subs[i].id = id - 1;
      subs[i].ac = "AC".equals(ac);  
    }

    boolean[] acs = new boolean[N];
    int[] penalties = new int[N];
    for (int i=0; i<N; i++) {
      acs[i] = false;
      penalties[i] = 0;
    }

    for (int i=0; i<M; i++) {
      Submission sub = subs[i];
      if (acs[sub.id]) {
        continue;
      } else if (sub.ac) {
        acs[sub.id] = true;
      } else {
        penalties[sub.id] += 1;
      }
    }

    int ac = 0;
    int penalty = 0;
    for (int i=0; i<N; i++) {
      if (acs[i]) {
        ac += 1;
        penalty += penalties[i];
      }
    }

    sc.close();
    System.out.println(ac + " " + penalty);
  }
}

