    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[][] a = new int[2][n];
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < n; j++) {
                    a[i][j] = in.nextInt();
                }
            }
            a[1][0] += a[0][0];
            for (int i = 1; i < n; i++) {
                a[0][i] += a[0][i - 1];
            }
            for (int i = 1; i < 2; i++) {
                for (int j = 1; j < n; j++) {
                    a[i][j] += Math.max(a[i - 1][j], a[i][j - 1]);
                }
            }
            out.println(a[1][n - 1]);
        }

    }

    static class InputReader {
