				count++;
				primeAr.add(num);
			}
		}
		System.out.println(count);
	}

	public static boolean isPrime(int i) {

		boolean prime = true;
		for (int j = 2; j <= Math.pow(i, 0.5); j++) {
			if (i % j == 0) {
				prime = false;
				break;
			}
		}
		return prime;
	}
}

