            int K = in.nextInt();

            int sum = 0;

            while (A > 0 && K > 0)
            {
                sum += 1;
                A--;
                K--;
            }
            while (B > 0 && K > 0)
            {
                B--;
                K--;
            }
            while (C > 0 && K > 0)
