/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author gaidash
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        BBuffet solver = new BBuffet();
        solver.solve(1, in, out);
        out.close();
    }

    static class BBuffet {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int[] a = in.nextIntArray(n);
            int[] gain = in.nextIntArray(n);
            int[] gainAfter = in.nextIntArray(n - 1);

            int ret = 0;
            int prev = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                int ith = a[i] - 1;
                ret += gain[ith];
                if (prev + 1 == ith) {
                    ret += gainAfter[prev];
                }
                prev = ith;
            }

            out.println(ret);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; ++i) array[i] = nextInt();
            return array;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }

    }
}

import java.util.Scanner;

public class Main{

	/**
	 * 2つの自然数x,yを入力とし、それらの最大公約数を求めるプログラム
	 * 
	 * @param args
	 */
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int x = scan.nextInt();
		int y = scan.nextInt();

		System.out.println(Gcd(x, y));

	}

	/**
	 * 最大公約数をもとめる
	 * 
	 * @param x
	 *            入力１
	 * @param y
	 *            入力２（x%y)
	 * @return 最大公約数
	 */
	public static int Gcd(int x, int y) {
		if (y > x) {
			int tmp;
			tmp = x;
			x = y;
			y = tmp;
		}

		if (y == 0) {
			return x;
		} else {
			return Gcd(y, x % y);
		}
	}
}

import java.util.*;
public class Main {
	public static void main(String[] args) {
		boolean result = true;
		//出発地点の初期化
		int t0 = 0, x0 = 0, y0 = 0;
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		for (int i=0;i<n;i++) {
			//目的地の更新
			int t1 = sc.nextInt();
			int x1 = sc.nextInt();
			int y1 = sc.nextInt();

			int t = t1-t0;
			int d = distance(x0,x1,y0,y1);
			//時間内に届くかを判定
			if (t < d) {
				result = false;
				break;
			}
			//偶奇が一致するか判定
			if (((t^d)&1)==1) {
				result = false;
				break;
			}
			//出発地点の更新
			t0 = t1;
			x0 = x1;
			y0 = y1;
		}
		System.out.println(result ? "Yes" : "No");
	}

	//2地点のマンハッタン距離を返す
	public static int distance(int x1, int x2, int y1, int y2) {
		x1 -= x2;
		y1 -= y2;
		if (x1<0)
			x1 *= -1;
		if (y1<0)
			y1 *= -1;
		return x1+y1;
	}
}

