public class Main {
	public static void main(String [] args) {
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int m = scan.nextInt();
		int l = scan.nextInt();
		long Matrix_A[][] = new long[n][m];
		long Matrix_B[][] = new long[m][l];
		long Matrix_C[][] = new long[n][l];

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < l; j++) {
				Matrix_C[i][j] = 0;
			}
		}

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				Matrix_A[i][j] = scan.nextLong();
			}
		}

		for(int i = 0; i < m; i++) {
			for(int j = 0; j < l; j++) {
				Matrix_B[i][j] = scan.nextLong();
			}
		}

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				for(int k = 0; k < l; k++) {
					Matrix_C[i][k] += Matrix_A[i][j] * Matrix_B[j][k]; 
				}
			}
		}

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < l; j++) {
