        double sum,a,m,sig,sigma;
        while(true) {
        	sum=0;
        	sig=0;
        	n=scan.nextInt();
        	if(n==0) {
        		break;
        	}
        	double s[]=new double[n];
        	for(i=0;i<n;i++) {
        		s[i]=scan.nextDouble();
