		int[]dp=new int[a.length];
		for(int i=1;i<a.length;i++) {
			int f1 = i-1>=0?(Math.abs(a[i]-a[i-1])+dp[i-1]):Integer.MAX_VALUE, f2=i-2>=0?(Math.abs(a[i]-a[i-2])+dp[i-2]):Integer.MAX_VALUE;
