     private static boolean isPrime(int a) {
        if(a < 2) {
            return false;
        }//if 
        if(a == 2) {
            return true;
        }//if
        if(a % 2 == 0) {
            return false;
        }//if

        double sqrt = Math.sqrt(a);
        for (int i = 3; i <= sqrt; i += 2) {
            if (a % i == 0) {
