public class Main {

    private static final int MOD = (int)1e9 + 7; //998244353;
    private static final long INF = (long)1e18;

    public Main(FastScanner in, PrintWriter out) {
        int K = in.nextInt();
        int[] ab = new int[K + 1];
        for (int a = 1; a <= K; a++) {
            for (int b = 1; b <= K; b++) {
                ab[gcd(a, b)]++;
            }
        }

        int res = 0;
        for (int c = 1; c <= K; c++) {
            for (int i = 1; i <= K; i++) {
                if (ab[i] == 0) continue;
                int x = gcd(c, i);
                res += x * ab[i];
            }
        }
        out.println(res);
    }

    private int gcd(int a, int b) {
        while (true) {
            if (b == 0) return a;
            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long pow(long x, long p) {
        long res = 1;
        while (p > 0) {
            if (p % 2 == 1)
                res = res * x % MOD;
            x = x * x % MOD;
            p /= 2;
        }
        return res;
    }

