		PrintWriter out = new PrintWriter(System.out);
		InputReader sc=new InputReader(System.in);
		int N=sc.nextInt();
		long[] A=sc.nextLongArray(N);
		HashSet<Long> hashSet=new HashSet<>();
		for (int i = 0; i < A.length; i++) {
